B = "ERROR 09:15:02 rollback of api-2 incomplete: volume detach timed out"
C = "ERROR 09:16:40 build 118 marked bad; pipeline halted at stage staging"

def lcs_substr(a,b):
    # returns longest common substring length and the substring
    m=[[0]*(len(b)+1) for _ in range(len(a)+1)]
    best=0; end=0
    for i in range(1,len(a)+1):
        for j in range(1,len(b)+1):
            if a[i-1]==b[j-1]:
                m[i][j]=m[i-1][j-1]+1
                if m[i][j]>best:
                    best=m[i][j]; end=i
    return best, a[end-best:end]

names = {'H':H,'A':A,'B':B,'C':C}
import itertools
for x,y in itertools.permutations(names,2):
    l, s = lcs_substr(names[x], names[y])
    if l>=3:
        print(x,y,l,repr(s))
