def overlap(x,y):
    maxk=0
    for k in range(1,min(len(x),len(y))+1):
        if x[-k:]==y[:k]:
            maxk=k
    return maxk

names = {'H':H,'A':A,'B':B,'C':C}
import itertools
for x,y in itertools.permutations(names,2):
    k = overlap(names[x],names[y])
    if k>0:
        print(x,'->',y,k)
